-- generated by oras_encounters.py; ids are resolved in-database, safe to re-run
START TRANSACTION;
CREATE TEMPORARY TABLE oras_have AS SELECT DISTINCT e.version_id, e.location_area_id, es.encounter_method_id FROM encounters e JOIN encounter_slots es ON es.id = e.encounter_slot_id WHERE e.version_id IN (25, 26);
CREATE TEMPORARY TABLE oras_stage (version_id INT, location_identifier VARCHAR(100), area_identifier VARCHAR(100) NULL, method_identifier VARCHAR(100), slot INT, rarity INT, pokemon_id INT, min_level INT, max_level INT);
SET @base := (SELECT COALESCE(MAX(id),0) FROM encounter_methods), @base_ord := (SELECT COALESCE(MAX(`order`),0) FROM encounter_methods), @n := 0;
SET @base := (SELECT COALESCE(MAX(id),0) FROM location_areas), @n := 0;
SET @base := (SELECT COALESCE(MAX(id),0) FROM location_areas), @n := 0;
SELECT ROW_COUNT() AS new_areas_created;
SET @base := (SELECT COALESCE(MAX(id),0) FROM encounter_slots), @n := 0;
SELECT COUNT(*) AS stage_rows, SUM((SELECT COUNT(*) FROM location_areas la JOIN locations l ON l.id = la.location_id WHERE l.identifier = s.location_identifier AND (s.area_identifier IS NULL OR la.identifier = s.area_identifier)) = 0) AS rows_with_no_matching_area FROM oras_stage s;
SET @base := (SELECT COALESCE(MAX(id),0) FROM encounters), @n := 0;
SELECT ROW_COUNT() AS encounters_inserted;
COMMIT;
